import { z } from "zod";

// ──────────────────────────────────────────────────────────
// CURRICULUM
// ──────────────────────────────────────────────────────────
export type LessonSection =
  | "structures"
  | "vocab"
  | "lecture"
  | "ecrit"
  | "revision"
  | "exam";

export type LessonIcon =
  | "Grammaire"
  | "Vocabulaire"
  | "Lecture"
  | "Écrit"
  | "Révision"
  | "Examen";

export interface CurriculumDay {
  day: number;
  theme: string;
  section: LessonSection;
  icon: LessonIcon;
}

// ──────────────────────────────────────────────────────────
// LESSON CONTENT (generated by the model)
// ──────────────────────────────────────────────────────────
export const QuestionSchema = z.object({
  question: z.string(),
  options: z.array(z.string()).length(4),
  correct: z.number().int().min(0).max(3),
  explanation: z.string(),
});

export const ExampleSchema = z.object({
  sentence: z.string(),
  note: z.string().optional(),
});

export const VocabItemSchema = z.object({
  word: z.string(),
  translation: z.string(),
  example: z.string().optional(),
});

export const ReadingSchema = z.object({
  passage: z.string(),
  questions: z.array(QuestionSchema),
});

export const LessonContentSchema = z.object({
  theory: z.string(),
  examples: z.array(ExampleSchema),
  reading: ReadingSchema,
  questions: z.array(QuestionSchema),
  writingPrompt: z.string(),
  vocab: z.array(VocabItemSchema),
});

export type Question = z.infer<typeof QuestionSchema>;
export type Example = z.infer<typeof ExampleSchema>;
export type VocabItem = z.infer<typeof VocabItemSchema>;
export type Reading = z.infer<typeof ReadingSchema>;
export type LessonContent = z.infer<typeof LessonContentSchema>;

// ──────────────────────────────────────────────────────────
// WRITING FEEDBACK
// ──────────────────────────────────────────────────────────
export interface WritingFeedbackMistake {
  excerpt: string;
  issue: string;
  correction: string;
  category: string; // narrowed to WritingCategory at the storage boundary
}

export interface WritingFeedback {
  score: number | null;
  feedback: string; // HTML
  mistakes: WritingFeedbackMistake[];
}

export interface WritingAttempt {
  text: string;
  feedback: WritingFeedback;
}

// ──────────────────────────────────────────────────────────
// USER PROGRESS (stored locally for now, ready for backend later)
// ──────────────────────────────────────────────────────────
export interface DayScore {
  qcm?: number;
  qcmTotal?: number;
  writingScore?: number | null;
}

export interface UserProgress {
  completedDays: number[];
  scores: Record<number, DayScore>;
  writings: Record<number, string>; // current draft
  writingAttempts: Record<number, WritingAttempt[]>; // graded attempts, oldest first
  vocabKnown: string[];
}

export const emptyProgress = (): UserProgress => ({
  completedDays: [],
  scores: {},
  writings: {},
  writingAttempts: {},
  vocabKnown: [],
});
